import * as React from "react";
declare function PageColumn({ className, ...props }: React.ComponentProps<"div">): React.JSX.Element;
declare function PageHeader({ title, description, action, className }: {
    title: React.ReactNode;
    description?: React.ReactNode;
    action?: React.ReactNode;
    className?: string;
}): React.JSX.Element;
/** A titled group of cards on a page: the title in body text, an action (a link or a button) at the right. */
declare function PageSection({ title, action, className, children }: {
    title?: React.ReactNode;
    action?: React.ReactNode;
    className?: string;
    children: React.ReactNode;
}): React.JSX.Element;
/**
 * Cards rise in one after another, 50ms apart, on the page's first render (the brand's content-in: a short rise and a
 * fade, ease-out); cards that mount later, after the page has entered, should render without it. Reduced motion
 * keeps the fade only.
 */
declare function PageRise({ index, className, children }: {
    index?: number;
    className?: string;
    children: React.ReactNode;
}): React.JSX.Element;
export { PageColumn, PageHeader, PageRise, PageSection };

